{
  "investigation_summary": "ホストWIN-32-H1上で2022-07-19 14:31:00から14:36:00の間に実行されたregsvr32.exeプロセスについて調査しました。親プロセスはexplorer.exeであり、コマンドラインにはDLLファイルの登録を示す引数が含まれていました。regsvr32.exeは複数のDLLファイルをロードし、いくつかのレジストリ操作を行っています。子プロセスの生成は確認されませんでしたが、ネットワーク接続としては外部IPへのHTTP通信が観測されました。これらの行動は通常のDLL登録操作に見えますが、外部通信の詳細とレジストリ操作の内容をさらに精査する必要があります。",
  "code_sequence": [
    "regsvr32.exe /s /n /i:user DLLファイル1.dll",
    "regsvr32.exe /s /n /i:user DLLファイル2.dll",
    "DLLファイル1.dllのロード",
    "DLLファイル2.dllのロード",
    "レジストリキーの作成・変更",
    "外部IPへのHTTP通信"
  ],
  "evidence": {
    "parent_process": {
      "process_name": "explorer.exe",
      "pid": 1234,
      "command_line": "C:\\Windows\\explorer.exe"
    },
    "target_process": {
      "process_name": "regsvr32.exe",
      "pid": 5678,
      "ppid": 1234,
      "command_line": "regsvr32.exe /s /n /i:user DLLファイル1.dll"
    },
    "file_operations": [
      "DLLファイル1.dllのロード",
      "DLLファイル2.dllのロード"
    ],
    "registry_operations": [
      "レジストリキーの作成・変更"
    ],
    "network_connections": [
      {
        "remote_ip": "203.0.113.45",
        "remote_port": 80,
        "protocol": "HTTP"
      }
    ]
  }
}
